import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Aggiungere testo a una foto richiede solo pochi minuti. Carichi l’immagine, scrivi le tue parole, scegli un font e un colore e metti il testo dove appartiene.</p>\n<p>Questa guida pratica ti accompagna per tutto il procedimento passo passo. Copre livelli singoli e multipli, scelte di font e dimensione, contorni e ombre e le impostazioni di esportazione che mantengono nitido il testo.</p>\n<p>Alla fine saprai mettere una didascalia a una foto, creare un meme, etichettare uno screenshot o progettare una grafica social su qualsiasi dispositivo. Tieni la foto originale finché non hai controllato il risultato.</p>\n<h2 id=\"before-you-start\">Prima di iniziare: pianifica le tue parole</h2>\n<p>Scrivi il tuo testo prima di aprire lo strumento. Una didascalia decisa in anticipo è più corta e più chiara di una inventata mentre fissi l’editor.</p>\n<p>Tienilo corto. Un titolo di poche parole e una didascalia di una riga funzionano molto meglio di un paragrafo, che nasconde la foto e sopraffà chi guarda.</p>\n<p>Decidi anche l’atmosfera. Un font audace si adatta a un meme o a un banner di saldi, mentre un leggero carattere con grazie si adatta a una foto di matrimonio o a una grafica di citazione.</p>\n<p>Apri lo <a href=\"/it/aggiungi-testo-immagine/\">strumento Aggiungi Testo a Immagine</a> nel browser. Tutto gira in locale, quindi la tua foto non viene mai caricata su un server.</p>\n<h2 id=\"step-by-step\">Aggiungi testo a un’immagine in sei passaggi</h2>\n<p>Il procedimento è lo stesso per una didascalia, un meme o un’etichetta. Carica, scrivi, dai uno stile, posiziona, controlla e scarica.</p>\n<p>Prenditi il tempo per il passaggio dello stile. Font, dimensione, colore e contorno decidono se il testo è leggibile oppure se sparisce nella foto.</p>\n<ol>\n<li>Carica l’immagine trascinandola nella zona di caricamento, scegliendola dal dispositivo oppure incollando uno screenshot con Ctrl+V.</li>\n<li>Clicca Aggiungi testo e scrivi la tua didascalia nel riquadro del contenuto di testo, usando Invio per le righe extra.</li>\n<li>Scegli un font, imposta la dimensione del testo tra il 2% e il 22% e scegli un colore che contrasta con la foto.</li>\n<li>Aggiungi un contorno di testo o un’ombra se lo sfondo è affollato, poi trascina il livello al suo posto.</li>\n<li>Aggiungi altri livelli per le righe extra, selezionando ognuno separatamente per dargli uno stile proprio.</li>\n<li>Scegli il formato di esportazione e la qualità, poi clicca Scarica per salvare l’immagine con didascalia.</li>\n</ol>\n<p>Apri il file scaricato una volta prima di condividerlo. Conferma che il testo si legga chiaramente e che nulla di importante nella foto sia coperto.</p>\n<h2 id=\"adding-your-first-layer\">Aggiungere il primo livello di testo</h2>\n<p>Clicca Aggiungi testo per creare il tuo primo livello. Lo strumento mette una didascalia predefinita sull’immagine, e tu la sostituisci con le tue parole nel riquadro del contenuto di testo.</p>\n<p>Scrivi le parole esattamente come vuoi che appaiano. Gli errori di ortografia su un’immagine sono difficili da non notare: leggi il testo due volte prima di andare avanti.</p>\n<p>Il livello appare al centro dell’immagine per impostazione predefinita. Trascinalo nella posizione che vuoi, come in alto per un titolo o in basso per una didascalia.</p>\n<p>Ogni livello è indipendente. Puoi dare a un livello uno stile in font grande e audace e a un altro in font piccolo e leggero, senza che i due si influenzino.</p>\n<h2 id=\"choosing-a-font\">Scegliere un font</h2>\n<p>Lo strumento include una serie di font integrati, da audaci senza grazie a classici con grazie. Scegli quello che corrisponde all’atmosfera della tua immagine e del tuo messaggio.</p>\n<p>Per meme e banner di saldi, usa un audace senza grazie. Le lettere pesanti restano leggibili a dimensioni piccole e su sfondi affollati, ed è esattamente ciò di cui ha bisogno un meme.</p>\n<p>Per citazioni e foto di matrimonio, usa un carattere con grazie o un font elegante. I tratti più leggeri sembrano formali e calmi, e si adattano a un messaggio riflessivo.</p>\n<p>Controlla il font alla dimensione con cui lo userai. Un font decorativo che sembra bellissimo a dimensioni grandi può diventare illeggibile quando è piccolo.</p>\n<h2 id=\"setting-text-size\">Impostare la dimensione del testo</h2>\n<p>La dimensione del testo va dal 2% al 22% dell’immagine. Un titolo vuole una dimensione più grande vicino al limite superiore dell’intervallo, mentre una didascalia o una riga di credito ne vogliono una più piccola.</p>\n<p>Il dimensionamento in percentuale mantiene il testo coerente su immagini di dimensioni diverse. La stessa impostazione sembra giusta su una piccola miniatura e su una grande foto di fotocamera.</p>\n<p>Prova la dimensione alle dimensioni con cui condividerai. Un titolo che sembra audace a dimensione intera potrebbe essere minuscolo in un’anteprima di feed social, dove l’immagine viene mostrata molto più piccola.</p>\n<p>Quando hai due livelli, dimensionali in modo diverso. Un grande titolo con una didascalia più piccola crea una chiara gerarchia, e chi guarda sa cosa leggere per primo.</p>\n<h2 id=\"choosing-a-colour\">Scegliere un colore di testo</h2>\n<p>Il testo bianco funziona sugli sfondi scuri e il testo nero funziona su quelli chiari, ma la maggior parte delle foto contiene entrambi. Controlla il colore rispetto all’area reale dove starà il testo.</p>\n<p>Metti il testo sopra la parte più semplice della foto. Una didascalia sopra un cielo limpido o un muro vuoto è molto più facile da leggere di una sopra una folla affollata.</p>\n<p>I colori luminosi possono funzionare per brevi titoli, ma sono più difficili da leggere nelle lunghe didascalie. Riserva i colori forti a poche parole, e usa bianco o nero per il resto.</p>\n<p>Se nessun colore funziona, aggiungi un pannello di sfondo. Un riquadro scuro semi-trasparente dietro il testo bianco lo rende leggibile ovunque, anche se copre una parte maggiore dell’immagine.</p>\n<h2 id=\"outline-and-shadow\">Aggiungere un contorno o un’ombra</h2>\n<p>Un contorno disegna un bordo intorno a ogni lettera. Un sottile contorno scuro intorno al testo bianco lo mantiene leggibile su un cielo luminoso, ed è per questo che i meme lo usano.</p>\n<p>Un’ombra fa sollevare il testo dallo sfondo. Aggiunge un morbido bordo scuro dietro le lettere, e questo le aiuta a risaltare senza l’aspetto duro di un contorno.</p>\n<p>Usa l’uno o l’altra, non entrambi a piena intensità. Un contorno più un’ombra pesante rende il testo disordinato, mentre un singolo effetto lo mantiene pulito.</p>\n<p>Per il testo classico dei meme, usa lettere bianche con un spesso contorno scuro. La combinazione è leggibile su quasi qualsiasi sfondo, ed è per questo che è diventata lo standard.</p>\n<h2 id=\"moving-layers\">Spostare e selezionare i livelli</h2>\n<p>Trascina un livello per spostarlo ovunque sull’immagine. Lo strumento permette di selezionare ogni livello separatamente quando ne hai diversi, così puoi modificarne uno senza toccare gli altri.</p>\n<p>Clicca il livello che vuoi modificare prima di cambiarne font, dimensione o colore. Modificare il livello sbagliato è un errore comune, ed è facile evitarlo controllando quale livello è attivo.</p>\n<p>Alto e basso sono le posizioni classiche per le didascalie. Un titolo in alto e una battuta finale in basso è il formato dei meme, e funziona perché l’occhio legge dall’alto in basso.</p>\n<p>Tieni il testo lontano dai bordi. Una didascalia che tocca il bordo sembra schiacciata, e le piattaforme ritagliano spesso di nuovo i bordi per schermi di dimensioni diverse.</p>\n<h2 id=\"rotating-text\">Ruotare i livelli di testo</h2>\n<p>I livelli di testo possono essere inclinati con angoli personalizzati, e questo aggiunge energia a un design. Un titolo leggermente diagonale sembra dinamico, mentre un testo dritto sembra calmo e formale.</p>\n<p>Usa la rotazione con parsimonia. Una piccola inclinazione di pochi gradi aggiunge carattere, mentre un angolo ripido rende il testo difficile da leggere e sembra un errore.</p>\n<p>Il testo diagonale funziona bene su poster e grafiche social, dove il design deve attirare l’occhio. Funziona male su istruzioni ed etichette, dove la chiarezza conta di più.</p>\n<p>Controlla il testo ruotato alla dimensione con cui verrà visto. Un’inclinazione che sembra a posto a dimensione intera può rendere il testo piccolo illeggibile in un’anteprima di feed.</p>\n<h2 id=\"multi-line-captions\">Didascalie su più righe e layout dei meme</h2>\n<p>Premi Invio dentro il riquadro del contenuto di testo per creare una nuova riga nello stesso livello. Questo permette di scrivere una didascalia che copre due o tre righe senza livelli extra.</p>\n<p>Per un meme, usa un livello per la didascalia in alto e uno per quella in basso. Livelli separati permettono di posizionare ogni riga esattamente dove appartiene.</p>\n<p>Tieni le righe corte. Una didascalia che corre su tutta la larghezza dell’immagine è difficile da leggere, mentre le righe corte centrate sul soggetto sono facili da seguire.</p>\n<p>Interrompi le righe alle pause naturali della frase. Un’interruzione di riga nel mezzo di una frase sembra goffa, mentre un’interruzione tra frasi sembra voluta.</p>\n<h2 id=\"making-a-meme\">Creare un meme in pochi minuti</h2>\n<p>Un meme è una foto con una breve didascalia divertente, di solito in testo bianco con un spesso contorno scuro in alto e in basso. Il formato è semplice, e quella semplicità è il punto.</p>\n<p>Carica la foto, aggiungi un livello in alto per l’impostazione e un livello in basso per la battuta finale. Tieni ogni riga a poche parole, così la battuta arriva in fretta.</p>\n<p>Usa un font audace e massiccio con un contorno scuro. L’aspetto classico dei meme resta leggibile su quasi qualsiasi sfondo, ed è per questo che è diventato lo standard.</p>\n<p>Controlla il meme in anteprima alla dimensione con cui verrà condiviso. Una battuta chiara a dimensione intera potrebbe essere illeggibile in una piccola anteprima di feed: controlla prima di pubblicare.</p>\n<h2 id=\"preview-and-export\">Controllare in anteprima ed esportare</h2>\n<p>Controlla sempre l’anteprima prima di scaricare. Verifica che il testo si legga chiaramente, che nulla di importante nella foto sia coperto e che i livelli siano nei posti giusti.</p>\n<p>Scegli JPG per le foto con testo con un’impostazione di qualità alta. I bordi del testo possono ammorbidirsi leggermente con la compressione JPG, quindi tieni alta la qualità per le piccole didascalie.</p>\n<p>Scegli PNG per screenshot e grafiche con testo. Il PNG è senza perdita, quindi i bordi delle lettere restano nitidi, e mantiene la trasparenza quando ti serve.</p>\n<p>Ricorda che il cursore di qualità si nasconde per il PNG, perché il PNG è senza perdita e non ha un’impostazione di qualità da regolare. È un comportamento normale, non un problema dello strumento.</p>\n<h2 id=\"adding-text-on-mobile\">Aggiungere testo da telefono o tablet</h2>\n<p>Lo strumento funziona sui touchscreen, quindi puoi mettere una didascalia a una foto direttamente dal telefono che l’ha scattata. Caricala dalla galleria, scrivi il testo e trascina il livello al suo posto con il dito.</p>\n<p>Scrivere sulla tastiera di un telefono è più lento, quindi scrivi la tua didascalia prima di aprire lo strumento. Una didascalia corta e pianificata è più facile da digitare di una inventata sul momento.</p>\n<p>Trascinare i livelli con un dito è meno preciso che con un mouse. Usa le aree centrale, superiore e inferiore come guide, e ingrandisci per controllare il posizionamento.</p>\n<p>I file scaricati finiscono nella solita cartella dei download. Da lì puoi condividere l’immagine con didascalia direttamente in una chat, in un’email o in un post social.</p>\n<h2 id=\"troubleshooting\">Risoluzione dei problemi comuni con il testo</h2>\n<p>Se il testo è illeggibile, il colore probabilmente corrisponde allo sfondo. Cambia il colore, aggiungi un contorno o sposta il livello in una parte più semplice della foto.</p>\n<p>Se hai modificato il livello sbagliato, clicca il livello che volevi cambiare e riprova. Lo strumento seleziona i livelli uno alla volta: controlla quale è attivo prima di dare uno stile.</p>\n<p>Se un livello non si sposta, controlla se lo hai selezionato prima. Un livello deve essere attivo prima di poter essere trascinato, e cliccarlo una volta di solito lo seleziona.</p>\n<p>Se il testo sembra sfocato dopo l’esportazione, l’impostazione di qualità JPG potrebbe essere troppo bassa. Esporta di nuovo con una qualità più alta, oppure passa al PNG per i bordi di testo più nitidi.</p>\n<h2 id=\"quick-tips\">Consigli rapidi per un testo migliore sulle immagini</h2>\n<p>Tieni il testo corto. Poche parole ben scelte rafforzano un’immagine, mentre un paragrafo stipato su una foto nasconde proprio la cosa che doveva descrivere.</p>\n<p>Usa al massimo un font per il titolo e uno per la didascalia. Mescolare molti caratteri sembra caotico, mentre una coppia coerente mantiene il design pulito.</p>\n<p>Controlla il testo alla dimensione con cui verrà visto. Una didascalia che sembra a posto a dimensione intera può essere illeggibile in un’anteprima di feed social.</p>\n<p>Salva la foto originale senza testo. Una volta che il testo è appiattito in un’esportazione, non può essere rimosso da quel file: l’originale è la tua unica copia pulita.</p>\n<h2 id=\"text-on-presentation-slides\">Aggiungere testo all’immagine di una slide di presentazione</h2>\n<p>Una foto usata come sfondo di una slide spesso ha bisogno di un titolo sopra. Aggiungi il titolo come livello di testo, usando un font grande e audace che resta leggibile dal fondo della sala.</p>\n<p>Metti il titolo sopra la parte più semplice della foto. Un titolo sopra un cielo limpido o un muro vuoto è molto più facile da leggere di uno sopra una folla affollata.</p>\n<p>Usa un contorno scuro o un’ombra quando lo sfondo è affollato. L’effetto solleva le lettere dalla foto quanto basta per leggerle, senza nascondere l’immagine sotto.</p>\n<p>Esporta l’immagine della slide in JPG con un’impostazione di qualità alta. Il testo deve restare nitido quando la slide viene proiettata, e un’esportazione di bassa qualità ammorbidirà le lettere.</p>\n<p>Per le regole di leggibilità, leggi <a href=\"/it/blog/testo-sulle-immagini-leggibilita-consigli/\">Testo sulle immagini: font, contrasto e leggibilità</a>. Per la panoramica completa, leggi <a href=\"/it/blog/aggiungere-testo-immagini-guida-completa/\">Aggiungere testo alle immagini: guida completa</a>, e per firmare la proprietà invece di aggiungere una didascalia, prova lo <a href=\"/it/aggiungi-filigrana-immagine/\">strumento Aggiungi Filigrana Immagine</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Come aggiungo testo a una foto dal telefono?","answer":"Apri lo strumento Aggiungi Testo a Immagine nel browser del telefono, carica la foto dalla galleria e tocca Aggiungi testo. Scrivi la didascalia, scegli un font e una dimensione, trascina il livello al suo posto con il dito e scarica il risultato."},{"question":"Posso aggiungere due didascalie diverse a un’immagine?","answer":"Sì. Aggiungi un livello separato per ogni didascalia, come uno in alto e uno in basso. Seleziona ogni livello da solo per dargli uno stile diverso, così il titolo può essere grande e audace mentre la didascalia resta più piccola."},{"question":"Perché il mio testo sembra sfocato dopo aver scaricato l’immagine?","answer":"L’impostazione di qualità JPG è probabilmente troppo bassa, e questo ammorbidisce i bordi delle lettere. Esporta di nuovo con un’impostazione di qualità più alta, oppure passa al PNG, che è senza perdita e mantiene nitidi i bordi del testo."},{"question":"Come creo un meme classico con testo in alto e in basso?","answer":"Carica la foto, aggiungi un livello per la riga in alto e un altro per la riga in basso, e usa un font audace senza grazie in bianco con un spesso contorno scuro. Tieni ogni riga a poche parole, così la battuta arriva in fretta."},{"question":"Posso spostare il testo dopo averlo scritto?","answer":"Sì. Seleziona il livello e trascinalo ovunque sull’immagine. Puoi spostare, ridimensionare, ricolorare e ruotare un livello in qualsiasi momento prima di scaricare. Una volta esportata l’immagine, il testo è appiattito dentro e non può essere spostato."},{"question":"Quanto dovrebbe essere grande il testo per un post Instagram?","answer":"Abbastanza grande da leggere in una piccola anteprima di feed, non solo a dimensione intera. I titoli vogliono una dimensione vicina al limite superiore dell’intervallo dal 2% al 22%. Prova il risultato guardando l’immagine esportata alla dimensione con cui apparirà nel feed."}];
